# Initially generated by GitHub Copilot.
from __future__ import annotations

from pathlib import Path

from repo_util.common import run_cmd, write_json, write_text
from repo_util.repo_selection import RepoInfo


def _split_patterns(include_pattern: str) -> list[str]:
    parts = [part.strip() for part in include_pattern.split(",")]
    return [part for part in parts if part]


def _line_term_stats(file_bytes: bytes) -> dict:
    cr_only = 0
    lf_only = 0
    crlf = 0

    index = 0
    while index < len(file_bytes):
        byte_value = file_bytes[index]
        if byte_value == 13:
            if index + 1 < len(file_bytes) and file_bytes[index + 1] == 10:
                crlf += 1
                index += 2
                continue
            cr_only += 1
            index += 1
            continue
        if byte_value == 10:
            lf_only += 1
            index += 1
            continue
        index += 1

    ends_with = "none"
    if file_bytes:
        last = file_bytes[-1]
        if last == 10:
            if len(file_bytes) >= 2 and file_bytes[-2] == 13:
                ends_with = "crlf"
            else:
                ends_with = "lf"
        elif last == 13:
            ends_with = "cr"

    return {
        "cr_only_count": cr_only,
        "lf_only_count": lf_only,
        "crlf_count": crlf,
        "has_cr_only": cr_only > 0,
        "has_lf_only": lf_only > 0,
        "has_crlf": crlf > 0,
        "ends_with": ends_with,
    }


def _mix_label(*, has_cr_only: bool, has_lf_only: bool, has_crlf: bool) -> str:
    if has_cr_only and not has_lf_only and not has_crlf:
        return "cr-only"
    if not has_cr_only and has_lf_only and not has_crlf:
        return "lf-only"
    if not has_cr_only and not has_lf_only and has_crlf:
        return "crlf-only"
    if has_cr_only and has_lf_only and not has_crlf:
        return "cr+lf"
    if has_cr_only and not has_lf_only and has_crlf:
        return "cr+crlf"
    if not has_cr_only and has_lf_only and has_crlf:
        return "lf+crlf"
    if has_cr_only and has_lf_only and has_crlf:
        return "cr+lf+crlf"
    return "no-line-terms"


def _tracked_files(repo_dir: Path, include_pattern: str) -> list[str]:
    patterns = _split_patterns(include_pattern)
    if not patterns:
        patterns = ["*.py"]

    result = run_cmd(["git", "-C", str(repo_dir), "ls-files", *patterns])
    if result.returncode != 0:
        raise RuntimeError(
            result.stderr.strip() or f"Failed to list tracked files for {repo_dir}"
        )
    return [line for line in result.stdout.splitlines() if line.strip()]


def _is_excluded(
    rel_path: str,
    *,
    exclude_novc: bool,
    exclude_dot_venv: bool,
    exclude_novc_prefix: bool,
) -> bool:
    normalized = rel_path.replace("\\", "/")
    basename = Path(normalized).name

    if exclude_dot_venv and "/.venv/" in f"/{normalized}/":
        return True
    if exclude_novc and "/.novc/" in f"/{normalized}/":
        return True
    if exclude_novc_prefix and basename.startswith("novc") and basename.endswith(".py"):
        return True
    return False


def _render_txt_report(results: list[dict]) -> str:
    lines: list[str] = []
    for repo in results:
        lines.append(f"=== {repo['repo']} ===")
        lines.append(f"today_commit: {repo['today_commit']}")
        lines.append(f"today_commit_source: {repo['today_commit_source']}")
        lines.append(f"py_file_count_scanned: {repo['py_file_count_scanned']}")
        ps = repo["presence_summary"]
        lines.append(
            "presence_summary: "
            f"cr_only_files={ps['files_with_cr_only']}, "
            f"lf_only_files={ps['files_with_lf_only']}, "
            f"crlf_files={ps['files_with_crlf']}"
        )
        ms = repo["mix_summary"]
        lines.append(
            "mix_summary: "
            f"cr-only={ms['cr-only']}, "
            f"lf-only={ms['lf-only']}, "
            f"crlf-only={ms['crlf-only']}, "
            f"cr+lf={ms['cr+lf']}, "
            f"cr+crlf={ms['cr+crlf']}, "
            f"lf+crlf={ms['lf+crlf']}, "
            f"cr+lf+crlf={ms['cr+lf+crlf']}, "
            f"no-line-terms={ms['no-line-terms']}"
        )
        es = repo["ends_with_summary"]
        lines.append(
            "ends_with_summary: "
            f"cr={es['cr']}, lf={es['lf']}, crlf={es['crlf']}, none={es['none']}"
        )

        if repo["mixed_files"]:
            lines.append("mixed_files:")
            for rel_path in repo["mixed_files"]:
                lines.append(f"  - {rel_path}")

        if repo["files_without_terminal_line_term"]:
            lines.append("files_without_terminal_line_term:")
            for rel_path in repo["files_without_terminal_line_term"]:
                lines.append(f"  - {rel_path}")

        lines.append("")

    return "\n".join(lines) + "\n"


def run_audit_line_terms_across_repos(
    repo_infos: list[RepoInfo],
    *,
    include_pattern: str,
    exclude_novc: bool,
    exclude_dot_venv: bool,
    exclude_novc_prefix: bool,
    report_json: Path | None,
    report_txt: Path | None,
) -> list[dict]:
    results: list[dict] = []

    for repo_info in repo_infos:
        tracked = _tracked_files(repo_info.path, include_pattern)
        filtered = [
            rel_path
            for rel_path in tracked
            if not _is_excluded(
                rel_path,
                exclude_novc=exclude_novc,
                exclude_dot_venv=exclude_dot_venv,
                exclude_novc_prefix=exclude_novc_prefix,
            )
        ]

        file_details: list[dict] = []
        for rel_path in filtered:
            full_path = repo_info.path / rel_path
            if not full_path.is_file():
                continue
            stats = _line_term_stats(full_path.read_bytes())
            mix = _mix_label(
                has_cr_only=stats["has_cr_only"],
                has_lf_only=stats["has_lf_only"],
                has_crlf=stats["has_crlf"],
            )
            file_details.append(
                {
                    "path": rel_path,
                    "cr_only_count": stats["cr_only_count"],
                    "lf_only_count": stats["lf_only_count"],
                    "crlf_count": stats["crlf_count"],
                    "has_cr_only": stats["has_cr_only"],
                    "has_lf_only": stats["has_lf_only"],
                    "has_crlf": stats["has_crlf"],
                    "mix": mix,
                    "ends_with": stats["ends_with"],
                }
            )

        mix_summary = {
            "cr-only": 0,
            "lf-only": 0,
            "crlf-only": 0,
            "cr+lf": 0,
            "cr+crlf": 0,
            "lf+crlf": 0,
            "cr+lf+crlf": 0,
            "no-line-terms": 0,
        }
        ends_with_summary = {"cr": 0, "lf": 0, "crlf": 0, "none": 0}

        for detail in file_details:
            mix_summary[detail["mix"]] += 1
            ends_with_summary[detail["ends_with"]] += 1

        files_with_cr_only = [
            detail for detail in file_details if detail["has_cr_only"]
        ]
        files_with_lf_only = [
            detail for detail in file_details if detail["has_lf_only"]
        ]
        files_with_crlf = [detail for detail in file_details if detail["has_crlf"]]
        mixed_files = [detail for detail in file_details if "+" in detail["mix"]]
        files_without_terminal = [
            detail for detail in file_details if detail["ends_with"] == "none"
        ]

        results.append(
            {
                "repo": repo_info.name,
                "today_commit": repo_info.head_commit,
                "today_commit_source": "head-committer-date",
                "py_file_count_scanned": len(file_details),
                "presence_summary": {
                    "files_with_cr_only": len(files_with_cr_only),
                    "files_with_lf_only": len(files_with_lf_only),
                    "files_with_crlf": len(files_with_crlf),
                },
                "mix_summary": mix_summary,
                "ends_with_summary": ends_with_summary,
                "mixed_files": [detail["path"] for detail in mixed_files],
                "files_without_terminal_line_term": [
                    detail["path"] for detail in files_without_terminal
                ],
                "files": file_details,
            }
        )

    if report_json is not None:
        write_json(report_json, results)
    if report_txt is not None:
        write_text(report_txt, _render_txt_report(results))

    print(f"REPO_COUNT={len(results)}")
    for repo in results:
        print(
            "REPO={0}; PY_FILES={1}; MIXED_FILES={2}; NO_TERM={3}".format(
                repo["repo"],
                repo["py_file_count_scanned"],
                len(repo["mixed_files"]),
                len(repo["files_without_terminal_line_term"]),
            )
        )

    return results
